def semver_sort(versions):
    def parse_version(v):
        # Split off build metadata
        if '+' in v:
            v, build = v.split('+', 1)
        else:
            build = ''

        # Split off pre-release
        if '-' in v:
            base, prerelease = v.split('-', 1)
        else:
            base = v
            prerelease = None

        # Parse base version
        parts = base.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        if prerelease is not None:
            prerelease_ids = prerelease.split('.')
            prerelease_tuple = []
            for identifier in prerelease_ids:
                if identifier.isdigit():
                    prerelease_tuple.append((0, int(identifier)))
                else:
                    prerelease_tuple.append((1, identifier))
            prerelease_tuple = tuple(prerelease_tuple)
        else:
            prerelease_tuple = None

        return (major, minor, patch, prerelease_tuple)

    def sort_key(item):
        index, v = item
        major, minor, patch, prerelease_tuple = parse_version(v)

        # For sorting: version without pre-release comes after version with pre-release
        # So we use (major, minor, patch, has_prerelease, prerelease_tuple, index)
        # where has_prerelease is False (0) if prerelease exists, True (1) if it doesn't
        if prerelease_tuple is None:
            return (major, minor, patch, 1, (), index)
        else:
            return (major, minor, patch, 0, prerelease_tuple, index)

    indexed_versions = list(enumerate(versions))
    sorted_versions = sorted(indexed_versions, key=sort_key)
    return [v for _, v in sorted_versions]

